bem_vindo = "seja bem vindo ao S.O.N.E.G.A"
intro = "Nessa historia voce é uma zeladora dos escritorios BAZINGA CORP, escritorio principal do empresarial BAZINGA"

intro_2 = "Hoje é o aniversario de 12 anos da sua FILHA e voce estava contando com a empatia do seu chefe para sair mais cedo e presenciar essa que sera uma linda festa com muitas decorações e DOCES feitos pelo seu marido, ele realmente tem melhorado muito......"

escolha = "oque voce vai fazer agora?"

ir_sala_chefe = "Você abre a porta da sala do seu chefe. Ou pelo menos era essa era sua intenção antes dela abrir na sua frente e seu colega Marcelo sair chorando da sala, suas mãos cobrindo os olhos. Você não têm a chance de chamá-lo para saber o que houve, por isso só entra e se depara com seu chefe fazendo círculos na testa com os dedos como quem está tenta se livrar do estresse."

ir_copa = "Você decide ir atrás de algo para comer antes de falar com seu chefe. Ele é bem casca grossa, aguentar as coisas mundanas que ele tem para dizer sobre insatisfações alheias fica mais fácil quando se tem uma barriga cheia."

ir_copa_2 = "Chegando na copa você encontra alguns trabalhadores reunidos e conversando antes de olhar nos armários e geladeira para se deparar com uma irritante ausência de qualquer comida que você tenha deixado guardada e escondida com o seu nome etiquetado. Você às vezes desconfia que o escritório tenha ratos mutantes comedores de plástico."

ir_copa_3 = "… Escondido no canto de um armário! Tem um pacote de… TRELOSO… seu marido que deu pra ti comer no trabalho um dia desses em um lapso de memória porque ele deve ter se esquecido que você ODEIA TRELOSO de morango…"

ir_copa_4 = "De qualquer prova você guarda o TRELOSO em seu INVENTÁRIO."

ir_trabalhadores = "Você decide puxar assunto com a moça e o cara sentados na mesa cochichando sobre alguma besteira. Você pergunta se eles não deveriam estar trabalhando, mas respondem que o setor deles tá com um problema no servidor em que eles simplesmente não conseguem fazer nada além de andar e esperar a hora de bater o point. Estranho que o chefe deixe eles perambular por aí mesmo que sem trabalho para fazer, mas você assente."

conversa_trabalhadores_1 = "Eles contam ter encontrado esse pedaço de metal que supostamente é o GATILHO de alguma arma especial que serve para neutralizar e acalmar um tipo específico de pessoa. Você pergunta como que eles vieram a saber de todas essas informações apenas a partir do objeto de metal e mencionam que estava tudo escrito em letras minúsculas no GATILHO."

conversa_trabalhadores_2 = "Trabalhador : Este gatilho é uma parte de uma arma especial que exerce a função de neutralizar e acalmar um tipo específico de pessoa” você conseguiu ler usando a lupa que lhe entregaram… Sinceramente você acha estranho que tenha um texto tão grande encravado num gatilho tão pequeno. E que eles se lembraram do texto palavra por palavra??? Ééé…"

conversa_trabalhadores_3 = "Você troca o pacote NOJENTO de biscoito TRELOSO com os dois trabalhadores bazinguenses. A troca é feita com entusiasmo unilateral, pois o entusiasmo de ter algo para comer por parte dos trabalhadores é diferente da sua curiosidade e confusão de olhar para esse GATILHO sem outras partes e se pergunta o que você vai fazer com ele para começo de conversa…Você não entende porque fez o que fez, mas guarda o GATILHO em seu INVENTÁRIO."